#ifndef BN_GPU_CUDA_NATIVE_MOE_VALIDATE_CUH
#define BN_GPU_CUDA_NATIVE_MOE_VALIDATE_CUH
#include "gpu_cuda_native_moe.h"
namespace bn_cuda_native_moe {
using bn_cuda_gdn::ResidentRequest;
static size_t workspace_size(void*vctx,int A){BnCudaCtx*ctx=(BnCudaCtx*)vctx;if(!ctx||ctx->compute_capability<800||A<1||A>16384*32||cuda_ctx_set_device(ctx))return 0;return bn_cuda_native_moe_sort_bytes(A);}
static int reserve(void*vctx,void*request,int A){BnCudaCtx*ctx=(BnCudaCtx*)vctx;ResidentRequest*r=(ResidentRequest*)request;if(!ctx||!r||r->backend_owner!=ctx||r->failed||A<1||A>16384*32||bn_cuda_gdn::set_device(r))return -1;if(r->native_moe_index_workspace)return A<=r->native_moe_max_assignments?0:-1;size_t bytes=workspace_size(vctx,A);if(!bytes)return -1;void*w=NULL;cudaError_t e=cudaMalloc(&w,bytes);if(e!=cudaSuccess){if(e==cudaErrorMemoryAllocation)(void)cudaGetLastError();return -1;}r->native_moe_index_workspace=w;r->native_moe_index_bytes=bytes;r->native_moe_max_assignments=A;return 0;}
static int views(void*vctx,void*request,const BnGPUResidentView*v,const size_t*counts,const int*types,const size_t*align,int n,void**data){BnCudaCtx*ctx=(BnCudaCtx*)vctx;ResidentRequest*r=(ResidentRequest*)request;if(!ctx||!r||r->backend_owner!=ctx||ctx->compute_capability<800||r->failed)return -1;for(int i=0;i<n;i++){if(v[i].count!=counts[i]||v[i].type!=types[i])return -1;data[i]=bn_cuda_gdn::view_data(r,v[i]);if(!data[i]||((uintptr_t)data[i]&(align[i]-1)))return -1;for(int j=0;j<i;j++)if(bn_cuda_gdn::overlap(v[i],v[j]))return -1;}return 0;}
static int index(void*vctx,void*request,const BnGPUNativeMoEIndexPlan*p){ResidentRequest*r=(ResidentRequest*)request;if(!p||bn_gpu_native_moe_shape(p->tokens,p->topk,p->experts)||!r||!r->native_moe_index_workspace||r->native_moe_max_assignments<p->tokens*p->topk)return -1;size_t A=(size_t)p->tokens*p->topk,E=(size_t)p->experts+1;BnGPUResidentView v[]={p->indices,p->weights,p->keys,p->values,p->sorted_keys,p->order,p->inverse,p->sorted_weights,p->counts,p->starts};size_t n[]={A,A,A,A,A,A,A,A,E,E},a[]={4,2,4,4,4,4,4,2,4,4};int t[]={BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_F16,BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_F16,BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_I32};void*d[10];if(views(vctx,request,v,n,t,a,10,d)||bn_cuda_gdn::set_device(r))return -1;int e=bn_cuda_native_moe_index(r->stream,r->native_moe_index_workspace,r->native_moe_index_bytes,d[0],d[1],d[2],d[3],d[4],d[5],d[6],d[7],d[8],d[9],(int)A,p->experts);if(e)r->failed=1;return e;}
static int group(void*vctx,void*request,const BnGPUNativeMoEGroupPlan*p){if(!p||p->tokens<1||p->tokens>16384||p->topk<1||p->topk>32||p->dim<128||p->dim>65536||p->dim%128||p->batch<1||p->batch>16||p->rows<1||p->rows>16384/p->batch)return -1;int A=p->tokens*p->topk,M=0;BnCudaNativeMoEGroup meta={};for(int b=0;b<p->batch;b++){int c=p->counts[b],s=p->starts[b];if(c<1||c>p->rows||c>p->tokens||s<0||s>A-c)return -1;meta.starts[b]=s;meta.counts[b]=c;if(c>M)M=c;}if(M!=p->rows)return -1;BnGPUResidentView v[]={p->x,p->order,p->out};size_t n[]={(size_t)p->tokens*p->dim,(size_t)A,(size_t)p->batch*p->rows*p->dim},a[]={16,4,16};int t[]={BN_GGUF_TENSOR_F16,BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_F16};void*d[3];ResidentRequest*r=(ResidentRequest*)request;if(views(vctx,request,v,n,t,a,3,d)||bn_cuda_gdn::set_device(r))return -1;int e=bn_cuda_native_moe_group(r->stream,&meta,d[0],d[1],d[2],p->tokens,p->topk,p->dim,p->rows,p->batch);if(e)r->failed=1;return e;}
static int reduce(void*vctx,void*request,const BnGPUNativeMoEReducePlan*p){if(!p||bn_gpu_native_moe_shape(p->tokens,p->topk,p->experts)||p->dim<128||p->dim>65536||p->dim%128||p->slot_rows<1||(size_t)p->slot_rows>SIZE_MAX/(size_t)p->dim/4)return -1;size_t A=(size_t)p->tokens*p->topk,E=p->experts;BnGPUResidentView v[]={p->indices,p->inverse,p->starts,p->slot_base,p->slot_kind,p->weights,p->slots,p->out};size_t n[]={A,A,E+1,E,E,A,(size_t)p->slot_rows*p->dim,(size_t)p->tokens*p->dim},a[]={4,4,4,4,4,2,4,4};int t[]={BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_I32,BN_GGUF_TENSOR_F16,BN_GGUF_TENSOR_F32,BN_GGUF_TENSOR_F32};void*d[8];ResidentRequest*r=(ResidentRequest*)request;if(views(vctx,request,v,n,t,a,8,d)||bn_cuda_gdn::set_device(r))return -1;int e=bn_cuda_native_moe_reduce(r->stream,d[7],d[6],d[0],d[1],d[2],d[3],d[4],d[5],p->tokens,p->dim,p->topk,p->experts,p->slot_rows);if(e)r->failed=1;return e;}
}
#endif
